const state={city:(()=>{try{return localStorage.getItem('areascout-city')||'Lagos'}catch{return 'Lagos'}})(),user:null,loading:true,inspections:null,convos:null,page:'home',selected:null,saved:JSON.parse(localStorage.getItem('areascout-saved')||'[]'),compare:[],query:'',location:'Yaba',sort:'Recommended',filters:{},chat:[]};
const view=document.querySelector('#view');
const money=n=>'₦'+Number(n).toLocaleString('en-NG');
