function setPage(page){state.page=page;state.selected=null;render();window.scrollTo({top:0,behavior:'smooth'});document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='messages')loadConvos();if(PAGE_LOADERS[page])PAGE_LOADERS[page]();if(page==='profile'&&state.user){loadInspections().then(()=>state.page==='profile'&&render()).catch(()=>{});api('/conversations').then(r=>{state.convos=r.conversations;if(state.page==='profile')render()}).catch(()=>{})}}
function areaSignal(label,grade){const n={Good:5,Fair:3,Poor:1}[grade]||0;const col=n>=4?'good':n>=2?'fair':n?'poor':'';return `<div class="signal"><span class="signal-name">${label}</span><span class="signal-bars">${[1,2,3,4,5].map(i=>`<i class="${i<=n?col:''}"></i>`).join('')}</span><b class="signal-grade ${col}-text">${grade||'No data'}</b></div>`}
function areaCard(a){return `<article class="area-card" data-area="${a.name}"><div class="area-top"><div><h3>${a.name}</h3><div class="area-meta">${a.listings} listings · ${a.reviews} local reports</div></div><span class="score">${a.score||'–'}<small>${a.score?'/100':''}</small></span></div><div class="signal-list">${areaSignal('Power',a.power)}${areaSignal('Flooding',a.flood)}${areaSignal('Security',a.security)}</div></article>`}
function total(h){return h.price+h.agency+h.legal+h.caution+h.service}
function listingCard(h){const saved=state.saved.includes(h.id),compared=state.compare.includes(h.id);return `<article class="listing-card" data-home="${h.id}"><div class="listing-photo" style="background-image:linear-gradient(180deg,#15243b06,#15243b18),url('${src(h.photo,800)}')"><span class="photo-tag">${h.verified?'✓ Verified listing':'New listing'}</span><button class="save-btn ${saved?'saved':''}" data-save="${h.id}" aria-label="${saved?'Remove saved home':'Save home'}">${saved?'♥':'♡'}</button></div><div class="listing-body"><div class="listing-price"><strong>${money(h.price)}<span style="font-size:10px;font-weight:500"> /year</span></strong><span>${h.beds} bed · ${h.baths} bath</span></div><div class="listing-title">${h.title}</div><div class="listing-meta">${h.meter} · ${h.compound}</div><div class="move-in"><span>Estimated move-in total</span><b>${money(total(h))}</b></div><button class="compare-toggle" data-compare="${h.id}">${compared?'✓ Added to compare':'＋ Add to compare'}</button></div></article>`}
function heading(kicker,title,desc,action=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action?`<div class="heading-actions">${action}</div>`:''}</div>`}
function homePage(){let results=inCity().filter(h=>`${h.title} ${h.street} ${h.area||''} ${h.city||''}`.toLowerCase().includes(state.query.toLowerCase()));if(state.filters.beds)results=results.filter(h=>h.beds>=state.filters.beds);if(state.filters.type)results=results.filter(h=>h.type===state.filters.type);if(state.filters.minRent)results=results.filter(h=>h.price>=state.filters.minRent);if(state.filters.maxRent)results=results.filter(h=>h.price<=state.filters.maxRent);if(state.filters.flood)results=results.filter(h=>h.flood==='Good');if(state.sort==='Lowest rent')results.sort((a,b)=>a.price-b.price);if(state.sort==='Move-in cost')results.sort((a,b)=>total(a)-total(b));return `${heading(new Date().toLocaleDateString('en-GB',{weekday:'long',day:'numeric',month:'long'}).toUpperCase(),greeting(),'Your next home should feel right on day one. Let’s find it.')}<section class="hero"><div class="hero-copy"><div class="eyebrow">A BETTER WAY TO RENT</div><h1>Know the area<br>before you sign.</h1><p>Find a home, understand the real move-in cost, and see what living there is like.</p></div><form class="search-panel" id="search-form"><input class="search-field location" id="location-search" aria-label="Area or street" placeholder="Area, street or landmark" value="${escapeHtml(state.query)}"><select class="search-field type" id="type-search" aria-label="Home type"><option value="">Any home type</option><option>Mini flat</option><option>Self-contain</option><option>2-bedroom flat</option><option>Terrace</option></select><button class="btn btn-teal search-btn">⌕ Search</button></form><div class="quick-filters"><button class="filter-chip ${state.filters.beds?'on':''}" data-filter="beds">2+ bedrooms</button><button class="filter-chip ${state.filters.flood?'on':''}" data-filter="flood">Low flood risk</button><button class="filter-chip" data-page="filters">＋ More filters</button></div></section><section class="section"><div class="section-head"><div><h2>Scout an area</h2><p>Real reports from people who live here</p></div><a class="text-link" href="#areas" data-action="all-areas">All areas →</a></div><div class="area-grid">${areas.map(areaCard).join('')}</div></section><section class="section" id="results"><div class="section-head"><div><h2>${state.query?'Homes matching your search':'Homes to explore'}</h2><p>${results.length} homes · transparent prices, local area reports</p></div>${(state.query||state.filters.type||state.filters.beds||state.filters.minRent||state.filters.maxRent)?`<button class="text-link" data-action="save-search">☆ Save this search</button>`:""}<button class="text-link" data-action="browse">See all homes →</button></div>${state.loading?'<div class="empty-state"><h2>Loading homes…</h2></div>':!inCity().length?`<div class="empty-state"><div class="empty-icon">⌖</div><h2>No homes in ${esc(state.city)} yet</h2><p>We’re growing city by city. Get a count of new homes here as soon as they’re listed, or look somewhere else.</p><button class="btn btn-primary" data-action="alert-city">Tell me when homes are listed</button> <button class="btn btn-outline" data-action="choose-city">Choose another city</button></div>`:results.length?`<div class="card-grid">${results.slice(0,3).map(listingCard).join('')}</div>`:empty('No homes match these filters','Try a different area or clear some filters.','Clear filters')}</section>`}
function empty(title,desc,button){return `<div class="empty-state"><div class="empty-icon">⌕</div><h2>${title}</h2><p>${desc}</p><button class="btn btn-primary" data-action="${button==='Clear filters'?'clear-filters':'home'}">${button}</button></div>`}
function savedPage(){const items=homes.filter(h=>state.saved.includes(h.id));return `${heading('YOUR SHORTLIST','Saved homes',items.length?`You’ve saved ${items.length} ${items.length===1?'home':'homes'}. Keep your favourites close.`:'Save homes you like and compare the details side by side.',`<button class="btn btn-primary" data-page="home">⌕ Explore homes</button>`)}${items.length?`<div class="toolbar"><span class="search-results"><strong>${items.length}</strong> saved properties</span><button class="btn btn-outline" data-page="compare">⇄ Compare selected</button></div><div class="card-grid">${items.map(listingCard).join('')}</div>`:empty('Your shortlist starts here','Tap the heart on a home to save it here. Your saved homes stay on this device.','Explore homes')}`}
function comparePage(){const items=homes.filter(h=>state.compare.includes(h.id));return `${heading('SIDE BY SIDE','Compare homes','See rent, move-in costs and area conditions together.',`<button class="btn btn-outline" data-page="home">＋ Add a home</button>`)}${items.length<2?`<div class="empty-state"><div class="empty-icon">⇄</div><h2>Choose homes to compare</h2><p>Add up to three homes to see the full cost and area signals side by side.</p><button class="btn btn-primary" data-page="home">Browse homes</button>${items.length?`<div style="margin-top:22px">${items.map(h=>`<button class="btn btn-outline" data-compare-remove="${h.id}">${h.title} ×</button>`).join(' ')}</div>`:''}</div>`:`<table class="compare-table"><tbody><tr><th>HOME</th>${items.map(h=>`<td><div class="compare-photo" style="background-image:url('${src(h.photo,500)}')"></div><span class="compare-name">${h.title}</span><div class="table-label">${h.verified?'✓ Verified':'Listing'}</div><div class="table-actions" style="margin-top:9px"><button class="btn btn-outline" data-home="${h.id}">Details</button><button class="btn btn-outline" data-compare-remove="${h.id}">Remove</button></div></td>`).join('')}</tr>${[['Annual rent',h=>money(h.price)],['Estimated move-in total',h=>money(total(h))],['Bedrooms',h=>h.beds],['Power',h=>h.power],['Flooding',h=>h.flood],['Security',h=>h.security],['Internet',h=>h.internet],['Meter',h=>h.meter]].map(([label,fn])=>`<tr><th>${label}</th>${items.map(h=>`<td>${fn(h)}</td>`).join('')}</tr>`).join('')}</tbody></table>`}`}
function detailPage(h){return `<button class="detail-back" data-action="back">← Back to homes</button><div class="detail-layout"><div><div class="gallery"><div class="listing-photo photo-1" style="background-image:url('${src(h.photo,1000)}')"></div><div class="listing-photo photo-2" style="background-image:url('${src('photo-1600607687939-ce8a6c25118c',600)}')"></div><div class="listing-photo photo-3" style="background-image:url('${src('photo-1600566753086-00f18fb6b3ea',600)}')"></div></div><div class="detail-title"><div><div class="eyebrow">${h.verified?'✓ VERIFIED LISTING':'AVAILABLE NOW'}</div><h1>${h.title}</h1><p>⌖ ${h.street} · ${h.city||state.city}</p></div><div class="detail-price">${money(h.price)} <small>/ year</small></div></div><div class="detail-stats"><span>⌂ &nbsp;${h.beds} bedrooms</span><span>◫ &nbsp;${h.baths} bathrooms</span><span>▤ &nbsp;${h.meter}</span></div><section class="detail-section"><h2>About this home</h2><p>${h.description||`${h.type} in ${h.area||h.city||state.city}. Ask the agent anything you need to feel confident, and see it in person before you pay.`}</p></section><section class="detail-section"><h2>What it’s like to live here</h2><div class="signal-panel">${[['Power',h.power],['Flooding',h.flood],['Security',h.security],['Internet',h.internet]].map(([a,b])=>`<div class="signal-tile">${areaSignal(a,b)}<div class="source">AREA REPORT</div></div>`).join('')}</div><button class="btn btn-quiet" data-action="area-report">See full area report →</button></section><section class="detail-section"><h2>What’s included</h2><p>${h.meter} · ${h.compound} · ${h.service?'Service charge ₦'+h.service.toLocaleString()+' / year':'No service charge listed'}</p></section>${agentSection(h)}</div><aside class="cost-card"><div class="eyebrow">NO SURPRISES</div><h2>Total move-in cost</h2><p>Estimated upfront costs based on this listing</p>${[['Annual rent',h.price],['Agency fee',h.agency],['Legal fee',h.legal],['Caution deposit',h.caution],['Service charge',h.service]].map(([a,b])=>`<div class="cost-row"><span>${a}</span><b>${money(b)}</b></div>`).join('')}<div class="cost-row total"><span>Estimated total</span><b>${money(total(h))}</b></div><div class="cost-note">Confirm all charges with the agent before paying. AreaScout never asks for an inspection fee.</div><button class="btn btn-primary btn-block" data-action="inspection">Request an inspection &nbsp; →</button><button class="btn btn-outline btn-block" data-action="message">▤ &nbsp; Message agent</button><button class="btn btn-quiet btn-block" data-save="${h.id}">${state.saved.includes(h.id)?'♥ Saved to your homes':'♡ Save this home'}</button></aside></div>`}
/* ---- AreaScout API client ---- */
const API=(window.AREASCOUT_API||'http://localhost:8000')+'/v1';
let token=localStorage.getItem('areascout-token'),afterAuth=null;
const esc=escapeHtml;
const SAMPLE_PHOTOS=['photo-1600593509214-6b8f3c0f7f5c','photo-1600607687939-ce8a6c25118c','photo-1600566753086-00f18fb6b3ea'];
async function api(path,{method='GET',body}={}){const res=await fetch(API+path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});let json=null;try{json=await res.json()}catch{}if(!res.ok){if(res.status===401&&token){token=null;localStorage.removeItem('areascout-token');state.user=null;paintUser()}const e=new Error(json?.errors?.length?json.errors.map(x=>x.message).join(', '):json?.message||'Something went wrong');e.status=res.status;throw e}return json?.data}
/* Text from the API is user-supplied and rendered through innerHTML, so escape it when mapping. */
const safePhoto=p=>/^https:\/\//.test(p||'')?encodeURI(p).replace(/['()]/g,c=>'%'+c.charCodeAt(0).toString(16).toUpperCase()):null;
const toArea=a=>({slug:a.slug,name:esc(a.name),description:esc(a.description),listings:a.listing_count,score:a.score,power:a.power,flood:a.flooding,security:a.security,internet:a.internet,transport:a.transport,water:a.water,reviews:a.community_reports,avg:a.rating_averages||{}});
const toHome=(l,areaBySlug)=>{const a=areaBySlug[l.area_slug]||{};return{id:l.id,city:esc(l.city),cityKey:String(l.city).toLowerCase(),title:esc(l.title),street:esc(l.address),type:esc(l.property_type),beds:l.bedrooms,baths:l.bathrooms,price:l.rent,agency:l.agency_fee,legal:l.legal_fee,caution:l.caution_deposit,service:l.service_charge+l.utilities,power:a.power,flood:a.flood,security:a.security,internet:a.internet,meter:esc(l.features[0]||'Ask the agent about power'),compound:esc(l.features[1]||l.area),photo:safePhoto(l.photos[0])||SAMPLE_PHOTOS[l.id%3],verified:l.verified,description:esc(l.description),area:esc(l.area)}};
const initials=n=>String(n||'?').split(/\s+/).map(w=>w[0]).slice(0,2).join('').toUpperCase();
const ago=iso=>{const m=Math.max(1,Math.round((Date.now()-new Date(iso))/60000));return m<60?m+' min ago':m<1440?Math.round(m/60)+' h ago':Math.round(m/1440)+' d ago'};
const persistSaved=()=>localStorage.setItem('areascout-saved',JSON.stringify(state.saved));
const NAV={
 tenant:{label:'DISCOVER',items:[['home','⌂','Explore'],['saved','♡','Saved homes <span class="nav-count" id="saved-count">0</span>'],['compare','⇄','Compare'],['messages','▤','Messages']],mobile:[['home','⌂','Explore'],['saved','♡','Saved'],['compare','⇄','Compare'],['profile','◉','Profile']]},
 host:{label:'MANAGE',items:[['host','▦','Dashboard'],['host-inspections','▣','Inspections'],['messages','▤','Messages']],mobile:[['host','▦','Dashboard'],['host-inspections','▣','Inspections'],['messages','▤','Messages'],['profile','◉','Profile']]},
 admin:{label:'MODERATE',items:[['admin','▦','Overview'],['admin-reports','⚑','Reports'],['admin-listings','⌂','Listings'],['admin-users','◎','Users'],['admin-reviews','★','Reviews']],mobile:[['admin','▦','Overview'],['admin-reports','⚑','Reports'],['admin-listings','⌂','Listings'],['admin-users','◎','Users']]},
};
const navKind=u=>!u||u.role==='tenant'?'tenant':u.role==='admin'?'admin':'host';
const ROLE_LANDING={host:'host',admin:'admin'};
const ROLE_ONLY=new Set(['host','host-inspections','editor','admin','admin-reports','report-review','admin-listings','admin-users','admin-reviews']);
function paintNav(){const n=NAV[navKind(state.user)];const nav=document.querySelector('.main-nav');nav.previousElementSibling.textContent=n.label;nav.innerHTML=n.items.map(([p,i,l])=>`<button class="nav-item${state.page===p?' active':''}" data-page="${p}"><span class="nav-icon">${i}</span>${l}</button>`).join('');document.querySelector('.mobile-nav').innerHTML=n.mobile.map(([p,i,l])=>`<button class="${state.page===p?'active':''}" data-page="${p}"><span>${i}</span>${l}</button>`).join('');const pill=document.querySelector('#location-pill');if(pill)pill.hidden=navKind(state.user)!=='tenant'}
/* After signing in or out, make sure the current page belongs to the role. */
function landOnRolePage(){const kind=navKind(state.user);if(kind!=='tenant'&&['home','saved','compare','filters','report'].includes(state.page))state.page=ROLE_LANDING[kind];if(kind==='tenant'&&ROLE_ONLY.has(state.page))state.page='home';if(!state.user&&ROLE_ONLY.has(state.page))state.page='home';state.selected=null;paintNav();if(PAGE_LOADERS[state.page])PAGE_LOADERS[state.page]()}
function paintUser(){Object.keys(detailCache).forEach(k=>delete detailCache[k]);const u=state.user;paintBell();document.querySelectorAll('.avatar:not(.profile-avatar)').forEach(el=>el.textContent=u?initials(u.name):'?');document.querySelector('.user-card b').textContent=u?u.name:'Guest';document.querySelector('.user-card small').textContent=u?u.role[0].toUpperCase()+u.role.slice(1)+' account':'Sign in to get started';landOnRolePage()}
async function loadInspections(){state.inspections=(await api('/inspections')).inspections;paintBell()}
async function loadConvos(){if(!state.user){state.convos=null;render();return}try{state.convos=(await api('/conversations')).conversations}catch(e){toast(e.message)}if(state.page==='messages')render()}
/* Anonymous saves stay on this device; on sign-in they are pushed to the account. */
async function syncSaved(){if(state.user?.role!=='tenant')return;for(const id of state.saved){try{await api('/saved/'+id,{method:'POST'})}catch{}}state.saved=(await api('/saved')).listings.map(l=>l.id);persistSaved()}
function requireAuth(fn){if(!state.user){afterAuth=fn;authModal();return}if(state.user.role!=='tenant'){toast('This needs a renter account');return}fn()}
function authModal(mode='signin'){const up=mode==='signup';modal(up?'Create your account':'Sign in',`<p>${up?'Create your account. Renters save homes, book inspections and message agents; landlords and agents list homes and manage visits.':'Sign in to continue.'}</p>${up?'<label for="auth-role">I am…</label><select id="auth-role"><option value="tenant">Looking to rent</option><option value="landlord">A landlord</option><option value="agent">An agent</option></select><label>Full name</label><input id="auth-name" autocomplete="name">':''}<label>Email</label><input id="auth-email" type="email" autocomplete="email"><label>Password</label><input id="auth-password" type="password" autocomplete="${up?'new-password':'current-password'}" placeholder="${up?'At least 10 characters':''}">${up?'':'<p><button class="text-link" data-action="forgot">Forgot your password?</button></p>'}<p><button class="text-link" data-auth-switch="${up?'signin':'signup'}">${up?'I already have an account':'New to AreaScout? Create an account'}</button></p>`,up?'Create account':'Sign in',async root=>{const email=root.querySelector('#auth-email').value.trim(),password=root.querySelector('#auth-password').value,name=root.querySelector('#auth-name')?.value.trim();if(!email||!password||(up&&!name)){toast('Fill in every field');return}try{const r=await api(up?'/auth/register':'/auth/login',{method:'POST',body:up?{name,email,password,role:root.querySelector('#auth-role')?.value||'tenant'}:{email,password}});token=r.token;localStorage.setItem('areascout-token',token);state.user=r.user;root.innerHTML='';paintUser();await syncSaved().catch(()=>{});loadInspections().catch(()=>{});toast('Welcome, '+r.user.name.split(' ')[0]);render();const next=afterAuth;afterAuth=null;if(next)requireAuth(next)}catch(e){toast(e.message)}})}
async function signOut(){try{await api('/auth/logout',{method:'POST'})}catch{}token=null;localStorage.removeItem('areascout-token');Object.assign(state,{user:null,inspections:null,convos:null,saved:[]});persistSaved();paintUser();render();toast('Signed out')}
async function openReport(name){state.reportArea=name;state.reportReviews=null;state.selected=null;state.page='report';render();const slug=areas.find(a=>a.name===name)?.slug;if(!slug)return;try{const r=await api('/areas/'+slug);const i=areas.findIndex(a=>a.slug===slug);areas[i]=toArea(r.area);state.reportReviews=r.reviews}catch(e){toast(e.message)}if(state.page==='report')render()}
function reportPage(a){if(!a)return empty('No area data yet','Area reports appear here once the AreaScout service is reachable.','Back home');const rows=[['Power','power','power'],['Flooding','flood','flooding'],['Security','security','security'],['Transport','transport','transport'],['Water','water','water'],['Internet','internet','internet']].map(([n,k,avgKey])=>[n,a[k]||'No data',a.avg[avgKey]?`Residents rate this ${a.avg[avgKey]}/5.`:'No resident ratings yet.']);const comments=state.reportReviews||[];return `<button class="detail-back" data-action="back">← Back</button>${heading('AREA REPORT','Living in '+a.name,'A practical picture of daily life, from resident reports and local sources.')}<div class="report-hero"><div class="report-score">${a.score||'–'}</div><div><h2>${a.score>=75?'A good place to start your search':a.score?'Worth a closer look':'No resident ratings yet'}</h2><p>${a.description}<br>Based on ${a.reviews} resident ${a.reviews===1?'report':'reports'}. Conditions can vary from street to street.</p></div></div><div class="report-grid">${rows.map(([n,g,d])=>`<article class="report-item"><div class="report-item-head"><h3>${n}</h3><span class="grade-pill grade-${g.toLowerCase().replace(' ','-')}">${g}</span></div><p>${d}</p><div class="signal-bars" style="margin-top:12px">${[1,2,3,4,5].map(i=>`<i class="${i<=({Good:5,Fair:3,Poor:1}[g]||0)?g.toLowerCase():''}"></i>`).join('')}</div><small>AREA REPORT</small></article>`).join('')}</div>${comments.length?`<section class="section"><div class="section-head"><div><h2>What residents say</h2></div></div>${comments.map(c=>`<article class="message-card"><div class="message-avatar">${esc(initials(c.reviewer))}</div><div class="message-content"><header><strong>${esc(c.reviewer)}</strong><time>${ago(c.created_at)}</time></header><p>${esc(c.comment)}</p></div></article>`).join('')}</section>`:''}<div class="community-cta"><div><strong>Help renters who come after you.</strong><span>Share what it’s really like to live in ${a.name}.</span></div><button class="btn btn-primary" data-action="review">＋ Add your report</button></div>`}
/* ---- Account: profile, password, notifications, saved searches, privacy ---- */
const ICONS={bell:'<path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21a8 8 0 0 1 16 0"/>',lock:'<rect x="4" y="11" width="16" height="10" rx="2"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/>',shield:'<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/>',search:'<circle cx="11" cy="11" r="7"/><path d="M21 21l-4.3-4.3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3.5 2.3c-.7.4-1 .9-1 1.7M12 17h.01"/>',out:'<path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4M16 17l5-5-5-5M21 12H9"/>',cal:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/>'};
const ico=n=>`<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]}</svg>`;
const rowHtml=(icon,title,desc,action)=>`<div class="setting-row" role="button" tabindex="0" data-action="${action}"><span class="setting-icon">${ico(icon)}</span><div><b>${title}</b><small>${desc}</small></div><span class="arrow">›</span></div>`;
function profilePage(){const u=state.user;return `${heading('YOUR ACCOUNT','Profile & settings','Manage your personal details and stay in control of your account.')}<div class="profile-layout"><div class="profile-card"><div class="avatar profile-avatar">${u?esc(initials(u.name)):'?'}</div><h2>${u?esc(u.name):'Guest'}</h2><p>${u?`${esc(u.email)}${u.phone?' · '+esc(u.phone):''} · ${u.role[0].toUpperCase()+u.role.slice(1)}`:'Sign in to keep saved homes across devices, book inspections and message agents.'}</p>${u?'<button class="btn btn-outline" data-action="edit-profile">Edit profile</button>':'<button class="btn btn-primary" data-action="signin">Sign in or create account</button>'}<div class="profile-stats"><div><b>${state.saved.length}</b><small>Saved</small></div><div><b>${state.inspections?state.inspections.length:'–'}</b><small>Inspections</small></div><div><b>${state.convos?state.convos.length:'–'}</b><small>Chats</small></div></div></div><div class="settings-card"><h2>Account settings</h2>${u?[...(u.role==='tenant'?[rowHtml('cal','Inspections & updates','Your requests and the agent’s replies','updates')]:[]),rowHtml('bell','Notifications','Choose what updates you receive','prefs'),...(u.role==='tenant'?[rowHtml('search','Saved searches','Your alerts and search preferences','searches')]:[]),rowHtml('lock','Password','Change the password you sign in with','password'),rowHtml('shield','Privacy & data','Download your data or delete your account','privacy'),rowHtml('help','Help & safety tips','Stay safe while finding your next home','safety'),rowHtml('out','Log out','Sign out of this device','signout')].join(''):rowHtml('help','Help & safety tips','Stay safe while finding your next home','safety')}</div></div>`}
const field=(id,label,attrs='')=>`<label for="${id}">${label}</label><input id="${id}" ${attrs}>`;
function editProfile(){const u=state.user;modal('Edit profile',`<p>Your email (${esc(u.email)}) can’t be changed here.</p>${field('ep-name','Full name',`value="${esc(u.name)}" autocomplete="name"`)}${field('ep-phone','Phone number',`value="${esc(u.phone||'')}" autocomplete="tel" placeholder="0803 000 0000"`)}`,'Save changes',async root=>{try{const r=await api('/me',{method:'PATCH',body:{name:root.querySelector('#ep-name').value.trim(),phone:root.querySelector('#ep-phone').value.trim()}});state.user={...state.user,...r.user};root.innerHTML='';paintUser();render();toast('Profile updated')}catch(e){toast(e.message)}})}
function changePassword(){modal('Change password',`<p>You’ll stay signed in here and be signed out on your other devices.</p>${field('pw-old','Current password','type="password" autocomplete="current-password"')}${field('pw-new','New password','type="password" autocomplete="new-password" placeholder="At least 10 characters"')}`,'Change password',async root=>{try{await api('/me/password',{method:'POST',body:{current_password:root.querySelector('#pw-old').value,new_password:root.querySelector('#pw-new').value}});root.innerHTML='';toast('Password changed')}catch(e){toast(e.message)}})}
const PREFS=[['inspection_updates','Inspection updates','When an agent confirms, declines or suggests a new time'],['messages','Messages','New messages from agents'],['saved_search_alerts','Saved search alerts','New homes that match a saved search'],['area_report_updates','Area reports','When your area report is reviewed']];
async function showPrefs(){let p;try{p=(await api('/me/preferences')).preferences}catch(e){toast(e.message);return}modal('Notifications',`<p>Updates always appear inside AreaScout. Email and push alerts aren’t switched on yet, so your choices are saved for when they are.</p>${PREFS.map(([k,t,d])=>`<label class="pref-row"><input type="checkbox" data-pref="${k}" ${p[k]?'checked':''}><span><b>${t}</b><small>${d}</small></span></label>`).join('')}`,'Save',async root=>{const body={};root.querySelectorAll('[data-pref]').forEach(i=>body[i.dataset.pref]=i.checked);try{await api('/me/preferences',{method:'PUT',body});root.innerHTML='';toast('Notification choices saved')}catch(e){toast(e.message)}})}
const filterSummary=f=>[f.city&&esc(f.city),f.q&&`“${esc(f.q)}”`,f.type&&esc(f.type),f.beds&&`${f.beds}+ bedrooms`,f.max_rent&&`under ${money(f.max_rent)}`,f.min_rent&&`from ${money(f.min_rent)}`,f.verified&&'verified only',f.area&&esc(f.area)].filter(Boolean).join(' · ');
async function showSearches(){let list;try{list=(await api('/saved-searches')).searches}catch(e){toast(e.message);return}state.searches=list;
 modal('Saved searches',list.length?list.map(s=>`<div class="message-card" style="align-items:center"><div class="message-content"><strong>${esc(s.name)}${s.new_count?` <span class="badge">${s.new_count} new</span>`:''}</strong><p>${filterSummary(s.filters)||'All homes'} · ${s.match_count} ${s.match_count===1?'match':'matches'}</p><label class="pref-row" style="padding:6px 0 0"><input type="checkbox" data-search-alerts="${s.id}" ${s.alerts?'checked':''}><span><small>Alert me about new matches</small></span></label></div><div style="display:grid;gap:6px"><button class="btn btn-outline" data-open-search="${s.id}">Open</button><button class="text-link" data-delete-search="${s.id}">Delete</button></div></div>`).join(''):'<p>Search for homes, then choose “Save this search” to be told when new ones match.</p>','Done',r=>r.innerHTML='')}
function saveSearch(){requireAuth(()=>{const f={city:state.city};if(state.query)f.q=state.query;if(state.filters.type)f.type=state.filters.type;if(state.filters.beds)f.beds=state.filters.beds;if(state.filters.minRent)f.min_rent=state.filters.minRent;if(state.filters.maxRent)f.max_rent=state.filters.maxRent;if(Object.keys(f).length<2){toast('Search or choose a filter first');return}
 modal('Save this search',`<p>${filterSummary(f)}</p>${field('ss-name','Name',`value="${esc([f.type,f.beds&&f.beds+'+ beds',f.q].filter(Boolean).join(' · ').slice(0,60))}"`)}<label class="pref-row"><input type="checkbox" id="ss-alerts" checked><span><small>Alert me about new matches</small></span></label>`,'Save search',async root=>{try{await api('/saved-searches',{method:'POST',body:{name:root.querySelector('#ss-name').value.trim()||'My search',filters:f,alerts:root.querySelector('#ss-alerts').checked}});root.innerHTML='';toast('Search saved — find it under Profile → Saved searches')}catch(e){toast(e.message)}})})}
function showPrivacy(){modal('Privacy & data',`<p>AreaScout keeps your account details, saved homes and searches, inspection requests, messages and area reports so the service works. You can take a copy or delete it all.</p><div style="display:grid;gap:10px"><button class="btn btn-outline" data-action="export-data">Download my data</button><button class="btn btn-outline" style="color:var(--red);border-color:var(--red)" data-action="delete-account">Delete my account…</button></div>`,'Done',r=>r.innerHTML='')}
async function exportData(){try{const data=await api('/me/export');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='areascout-my-data.json';document.body.appendChild(a);a.click();a.remove();toast('Your data has been downloaded')}catch(e){toast(e.message)}}
function deleteAccount(){modal('Delete your account?',`<p>This removes your saved homes and searches and signs you out everywhere. Messages you sent stay visible to the other person, but without your name. ${state.user.role==='tenant'?'':'Your listings will be taken down. '}This can’t be undone.</p>${field('da-pw','Enter your password to confirm','type="password" autocomplete="current-password"')}`,'Delete my account',async root=>{try{await api('/me',{method:'DELETE',body:{password:root.querySelector('#da-pw').value}});root.innerHTML='';token=null;localStorage.removeItem('areascout-token');Object.assign(state,{user:null,inspections:null,convos:null,saved:[]});persistSaved();paintUser();setPage('home');toast('Your account has been deleted')}catch(e){toast(e.message)}})}
document.addEventListener('click',async e=>{const o=e.target.closest('[data-open-search]'),d=e.target.closest('[data-delete-search]');if(o){const s=(state.searches||[]).find(x=>x.id===Number(o.dataset.openSearch));if(!s)return;api(`/saved-searches/${s.id}/seen`,{method:'POST'}).catch(()=>{});if(s.filters.city&&s.filters.city.toLowerCase()!==state.city.toLowerCase())await changeCity(s.filters.city);state.query=s.filters.q||'';state.filters={};if(s.filters.type)state.filters.type=s.filters.type;if(s.filters.beds)state.filters.beds=s.filters.beds;if(s.filters.min_rent)state.filters.minRent=s.filters.min_rent;if(s.filters.max_rent)state.filters.maxRent=s.filters.max_rent;document.querySelector('#modal-root').innerHTML='';setPage('home');return}
 if(d){try{await api(`/saved-searches/${d.dataset.deleteSearch}`,{method:'DELETE'});showSearches()}catch(err){toast(err.message)}return}
 const act=e.target.closest('[data-action]')?.dataset.action;if(act==='edit-profile')editProfile();if(act==='prefs')showPrefs();if(act==='searches')showSearches();if(act==='password')changePassword();if(act==='privacy')showPrivacy();if(act==='export-data')exportData();if(act==='delete-account')deleteAccount();if(act==='save-search')saveSearch()});
document.addEventListener('change',async e=>{const a=e.target.closest('[data-search-alerts]');if(a){try{await api(`/saved-searches/${a.dataset.searchAlerts}`,{method:'PATCH',body:{alerts:a.checked}})}catch(err){toast(err.message);a.checked=!a.checked}}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('.setting-row[data-action]')){e.preventDefault();e.target.click()}});
function messagesPage(){const head=heading('YOUR INBOX','Messages','Keep conversations with property agents in one place.'),c=state.convos;if(!state.user)return head+`<div class="empty-state"><div class="empty-icon">▤</div><h2>Sign in to see your messages</h2><p>Conversations with agents stay on the platform, in one place.</p><button class="btn btn-primary" data-action="signin">Sign in</button></div>`;if(!c)return head+`<div class="empty-state"><h2>Loading messages…</h2></div>`;if(!c.length)return head+`<div class="empty-state"><div class="empty-icon">▤</div><h2>No conversations yet</h2><p>${state.user.role==='tenant'?'Message an agent from any home to start one.':'When a renter messages you about a listing, you can reply here.'}</p>${state.user.role==='tenant'?'<button class="btn btn-primary" data-page="home">Browse homes</button>':''}</div>`;return head+c.map(x=>`<article class="message-card" data-action="open-thread" data-id="${x.id}"><div class="message-avatar">${esc(initials(x.with))}</div><div class="message-content"><header><strong>${esc(x.with)}</strong><time>${ago(x.updated_at)}</time></header><p class="message-listing">${esc(x.listing_title)}</p><p>${esc(x.last_message)}</p></div>${x.unread?`<span class="badge">${x.unread} new</span>`:''}</article>`).join('')}
async function openThread(id){let t;try{t=await api('/conversations/'+id)}catch(e){toast(e.message);return}const me=state.user.id;modal(esc(t.conversation.listing_title),`<div style="max-height:280px;overflow:auto;display:grid;gap:8px;margin-bottom:12px">${t.messages.map(m=>`<div style="justify-self:${m.sender_id===me?'end':'start'};max-width:80%;padding:9px 12px;border-radius:12px;background:${m.sender_id===me?'var(--mint)':'#eef0f4'}">${esc(m.body)}<div style="font-size:10px;color:var(--muted);margin-top:3px">${ago(m.created_at)}</div></div>`).join('')}</div><label>Reply</label><textarea id="reply-text" placeholder="Write a message"></textarea>`,'Send',async root=>{const val=root.querySelector('#reply-text').value.trim();if(!val){toast('Write a message first');return}try{await api(`/conversations/${id}/messages`,{method:'POST',body:{message:val}})}catch(e){toast(e.message);return}loadConvos();openThread(id)})}
function filtersPage(){return `${heading('FIND YOUR FIT','Search filters','Narrow down to homes that fit your budget and your everyday needs.')}<div class="settings-card" style="max-width:660px"><label>Home type</label><select id="filter-type" class="field"><option value="">Any type</option><option>Self-contain</option><option>Mini flat</option><option>2-bedroom flat</option><option>Terrace</option></select><label>Minimum bedrooms</label><select id="filter-beds" class="field"><option value="0">Any</option><option value="1">1 bedroom</option><option value="2">2+ bedrooms</option><option value="3">3+ bedrooms</option></select><label>Yearly rent (₦)</label><div style="display:flex;gap:10px"><input id="filter-min" class="field" inputmode="numeric" placeholder="Min" value="${state.filters.minRent||''}"><input id="filter-max" class="field" inputmode="numeric" placeholder="Max" value="${state.filters.maxRent||''}"></div><label>Area condition</label><div style="padding:12px 0;color:#657186"><label style="display:flex;align-items:center;gap:8px"><input type="checkbox" id="filter-flood"> Low flood risk only</label></div><button class="btn btn-primary" data-action="apply-filters">Show matching homes →</button></div>`}
function greeting(){const h=new Date().getHours();return (h<12?'Good morning':h<18?'Good afternoon':'Good evening')+(state.user?', '+esc(state.user.name.split(' ')[0]):'')}
/* The list endpoint leaves out the lister's rating and phone; the single-listing one has them. */
const detailCache={};
function loadDetail(id){if(detailCache[id]!==undefined)return;detailCache[id]=null;api('/listings/'+id).then(r=>{detailCache[id]=r.listing;if(state.selected===id)render()}).catch(()=>{delete detailCache[id]})}
const phoneDigits=p=>String(p||'').replace(/[^\d+]/g,'');
const waNumber=p=>{const d=String(p||'').replace(/\D/g,'');return d.startsWith('0')?'234'+d.slice(1):d};
function agentSection(h){const d=detailCache[h.id];if(!d)return '<section class="detail-section"><h2>Listed by</h2><p>Loading…</p></section>';const r=d.owner_rating,mine=state.user&&state.user.id===d.owner_id;return `<section class="detail-section"><h2>Listed by</h2><p><b>${esc(d.owner_name)}</b>${d.owner_verified?' · Verified':''} · ${r&&r.count?`★ ${r.average} (${r.count} ${r.count===1?'review':'reviews'})`:'No reviews yet'}</p>${d.owner_phone&&!mine?`<div style="display:flex;gap:10px;flex-wrap:wrap"><a class="btn btn-outline" href="tel:${phoneDigits(d.owner_phone)}">Call</a><a class="btn btn-outline" target="_blank" rel="noopener" href="https://wa.me/${waNumber(d.owner_phone)}?text=${encodeURIComponent('Hi, I’m interested in “'+d.title+'” on AreaScout.')}">WhatsApp</a></div>`:state.user||!d.owner_phone?'':'<p><small>Sign in to see how to contact them directly.</small></p>'}</section>`}
function render(){const sc=document.querySelector('#saved-count');if(sc)sc.textContent=state.saved.length;document.querySelector('#crumb').textContent=({home:'Explore',saved:'Saved homes',compare:'Compare',profile:'Profile',messages:'Messages',filters:'Filters',report:'Area report',...EXTRA_CRUMBS})[state.page]||'Explore';if(state.selected){loadDetail(state.selected);view.innerHTML=detailPage(homes.find(h=>h.id===state.selected));return}view.innerHTML=({home:homePage,saved:savedPage,compare:comparePage,profile:profilePage,messages:messagesPage,filters:filtersPage,report:()=>reportPage(areas.find(a=>a.name===state.reportArea)||areas[0]),...EXTRA_PAGES})[state.page]?.()||homePage();}
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let toastTimer;function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2300)}
function modal(title,body,submitLabel,callback){const root=document.querySelector('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-top"><h2>${title}</h2><button class="modal-close" data-action="close-modal">×</button></div>${body}<button class="btn btn-primary btn-block" data-action="modal-submit">${submitLabel}</button></section></div>`;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''});root.querySelector('[data-action="modal-submit"]').onclick=()=>{callback(root);};}
async function save(id){const was=state.saved.includes(id);if(state.user){if(state.user.role!=='tenant'){toast('Only renter accounts can save homes');return}try{await api('/saved/'+id,{method:was?'DELETE':'POST'})}catch(e){toast(e.message);return}}state.saved=was?state.saved.filter(x=>x!==id):[...state.saved,id];persistSaved();toast(was?'Removed from saved homes':'Home saved to your shortlist');render()}
function startMessage(){requireAuth(()=>{const h=homes.find(h=>h.id===state.selected);modal('Message the agent',`<p>Ask a question about <b>${h?.title||'this home'}</b>. Keep payments and conversations on the platform.</p><label>Your message</label><textarea id="message-text" placeholder="Hi, is this home still available? I’d like to arrange a viewing."></textarea>`,'Send message',async root=>{const val=root.querySelector('textarea').value.trim();if(!val){toast('Write a message first');return}try{await api('/conversations',{method:'POST',body:{listing_id:h.id,message:val}})}catch(e){toast(e.message);return}root.innerHTML='';setPage('messages');toast('Message sent to the agent')})})}
function startInspection(){requireAuth(()=>{const h=homes.find(h=>h.id===state.selected);modal('Request an inspection',`<p>Choose a convenient time to view <b>${h?.title}</b>. The agent will confirm your request.</p><label>Preferred date</label><input id="inspect-date" type="date" min="${new Date().toISOString().slice(0,10)}"><label>Preferred time</label><select id="inspect-time"><option>Morning · 9am–12pm</option><option>Afternoon · 12pm–3pm</option><option>Late afternoon · 3pm–6pm</option></select><label>Note for the agent (optional)</label><textarea id="inspect-note" placeholder="Anything you'd like to check during the visit?"></textarea>`,'Send request',async root=>{const date=root.querySelector('#inspect-date').value;if(!date){toast('Choose a preferred date');return}const hour=[10,13,16][root.querySelector('#inspect-time').selectedIndex];try{await api('/inspections',{method:'POST',body:{listing_id:h.id,requested_at:new Date(`${date}T${String(hour).padStart(2,'0')}:00:00`).toISOString(),note:root.querySelector('#inspect-note').value.trim()}});loadInspections().catch(()=>{})}catch(e){toast(e.message);return}root.innerHTML='';toast('Inspection request sent. We’ll notify you when the agent replies.')})})}
function startReview(){requireAuth(()=>{const a=areas.find(a=>a.name===state.reportArea);if(!a?.slug){toast('Area reports need a connection to AreaScout');return}modal('Share an area report',`<p>Your experience of living in <b>${a.name}</b> helps renters make more informed choices.</p><label>What would you like to report?</label><select id="rev-field"><option value="power">Power supply</option><option value="flooding">Flooding</option><option value="security">Security</option><option value="transport">Traffic</option><option value="water">Water</option><option value="internet">Internet</option></select><label>How is it? (1 = poor, 5 = great)</label><select id="rev-rating">${[1,2,3,4,5].map(n=>`<option${n===3?' selected':''}>${n}</option>`).join('')}</select><label>Your experience</label><textarea id="rev-text" placeholder="What should someone moving here know?"></textarea><p>Reports are reviewed before they appear. Please don’t include personal information.</p>`,'Submit report',async root=>{try{await api('/area-reviews',{method:'POST',body:{area:a.slug,[root.querySelector('#rev-field').value]:Number(root.querySelector('#rev-rating').value),comment:root.querySelector('#rev-text').value.trim()}})}catch(e){toast(e.message);return}root.innerHTML='';toast('Thanks — your report is queued for review.')})})}
document.addEventListener('click',e=>{const page=e.target.closest('[data-page]');if(page){e.preventDefault();if(page.dataset.page==='filters')state.page='filters';else setPage(page.dataset.page);if(state.page==='filters')render();return}const saveBtn=e.target.closest('[data-save]');if(saveBtn){e.stopPropagation();save(Number(saveBtn.dataset.save));return}const compareBtn=e.target.closest('[data-compare]');if(compareBtn){e.stopPropagation();const id=Number(compareBtn.dataset.compare);if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length>=3)toast('Compare up to three homes at a time');else{state.compare.push(id);toast('Added to compare')}render();return}const home=e.target.closest('[data-home]');if(home){state.selected=Number(home.dataset.home);render();window.scrollTo({top:0,behavior:'smooth'});return}const area=e.target.closest('[data-area]');if(area){openReport(area.dataset.area);return}const remove=e.target.closest('[data-compare-remove]');if(remove){state.compare=state.compare.filter(id=>id!==Number(remove.dataset.compareRemove));render();return}const act=e.target.closest('[data-action]')?.dataset.action;if(!act)return;if(act==='back'){state.selected=null;state.page='home';render()}if(act==='area-report'){openReport(homes.find(h=>h.id===state.selected)?.area||areas[0]?.name)}if(act==='inspection')startInspection();if(act==='message')startMessage();if(act==='clear-filters'){state.query='';state.filters={};render()}if(act==='home')setPage('home');if(act==='browse'){state.query='';render();document.querySelector('.section:last-of-type')?.scrollIntoView({behavior:'smooth'})}if(act==='all-areas')toast('Pick an area card to read its report.');if(act==='apply-filters'){state.filters={type:document.querySelector('#filter-type').value,beds:Number(document.querySelector('#filter-beds').value),flood:document.querySelector('#filter-flood').checked,minRent:Number(document.querySelector('#filter-min').value.replace(/\D/g,''))||0,maxRent:Number(document.querySelector('#filter-max').value.replace(/\D/g,''))||0};if(!state.filters.type)delete state.filters.type;if(!state.filters.beds)delete state.filters.beds;if(!state.filters.minRent)delete state.filters.minRent;if(!state.filters.maxRent)delete state.filters.maxRent;setPage('home')}if(act==='close-modal')document.querySelector('#modal-root').innerHTML=''});
document.querySelector('#view').addEventListener('click',e=>{const card=e.target.closest('.listing-card');if(card&&!e.target.closest('button')){state.selected=Number(card.dataset.home);render();window.scrollTo({top:0,behavior:'smooth'})}});
document.querySelector('#view').addEventListener('submit',e=>{if(e.target.id==='search-form'){e.preventDefault();state.query=document.querySelector('#location-search').value.trim();state.filters.type=document.querySelector('#type-search').value;render();showResults()}});
document.querySelector('#view').addEventListener('change',e=>{if(e.target.id==='sort-select'){state.sort=e.target.value;render()}});
document.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(!f)return;const k=f.dataset.filter;if(k==='beds')state.filters.beds=state.filters.beds?0:2;if(k==='flood')state.filters.flood=!state.filters.flood;render();showResults()});
async function showUpdates(){if(!state.user){authModal();return}if(state.user.role!=='tenant'){setPage(state.user.role==='admin'?'admin-reports':'host-inspections');return}try{await loadInspections()}catch(e){toast(e.message);return}const label={pending:'requested',confirmed:'confirmed',declined:'declined',new_time:'needs a new time',cancelled:'cancelled'};modal('Notifications',state.inspections.length?state.inspections.map(i=>`<div class="message-card"><span class="message-avatar">${i.status==='confirmed'?'✓':'⌂'}</span><div class="message-content"><strong>Inspection ${label[i.status]||i.status}</strong><p>${esc(i.listing_title||'Home')} · ${new Date(i.requested_at).toLocaleString('en-GB',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'})}</p>${i.owner_note?`<p>${esc(i.owner_note)}</p>`:''}${i.can_review?`<button class="btn btn-outline" data-rate="${i.id}" data-owner="${esc(i.owner_name||'')}">Rate ${esc(i.owner_name||'your visit')}</button>`:''}</div></div>`).join(''):'<p>No updates yet.</p>','Got it',root=>root.innerHTML='')}
document.querySelector('.notification').addEventListener('click',showUpdates);
function paintBell(){const dot=document.querySelector('.notification i');if(dot)dot.hidden=!(state.inspections||[]).some(i=>['confirmed','declined','new_time'].includes(i.status))}
document.addEventListener('click',e=>{const sw=e.target.closest('[data-auth-switch]');if(sw){authModal(sw.dataset.authSwitch);return}const act=e.target.closest('[data-action]');if(!act)return;const a=act.dataset.action;if(a==='signin')authModal();if(a==='updates')showUpdates();if(a==='safety')modal('Stay safe','<p>Inspect the home and see the documents before you pay anything. AreaScout never asks for an inspection fee, and will never ask you to pay a fee through chat.</p>','Got it',r=>r.innerHTML='');if(a==='signout')signOut();if(a==='open-thread')openThread(Number(act.dataset.id));if(a==='review')startReview()});
/* Results sit below the hero and the area cards, so scroll to them after a search or filter change. */
function showResults(){const el=document.querySelector('#results');if(el&&el.scrollIntoView)el.scrollIntoView({behavior:'smooth',block:'start'});suggestElsewhere()}
/* Searching is limited to the chosen city, so when it finds nothing, say where it would. */
async function suggestElsewhere(){const q=state.query.trim(),box=document.querySelector('#results .empty-state');if(!q||!box||box.querySelector('[data-city]'))return;
 try{const{listings}=await api('/listings?q='+encodeURIComponent(q));if(state.query.trim()!==q)return;const here=state.city.toLowerCase(),by={};listings.forEach(l=>{if(l.city.toLowerCase()!==here)by[l.city]=(by[l.city]||0)+1});const entries=Object.entries(by);if(!entries.length)return;
  const live=document.querySelector('#results .empty-state');if(!live)return;live.insertAdjacentHTML('beforeend',`<p style="margin-top:14px">No matches for “${esc(q)}” in ${esc(state.city)}, but there ${entries.length===1&&entries[0][1]===1?'is':'are'}:</p><div class="city-list" style="max-width:340px;margin:8px auto 0">${entries.map(([c,n])=>`<button class="city-btn" data-city="${esc(c)}" data-keep>${esc(c)}<small>${n} ${n===1?'home':'homes'}</small></button>`).join('')}</div>`)}catch{}}
const inCity=()=>homes.filter(h=>h.cityKey===state.city.toLowerCase());
const paintCity=()=>{document.querySelector('#city-label').textContent=state.city;document.querySelector('#footer-city').textContent=state.city;document.querySelector('#location-pill').setAttribute('aria-label','Location: '+state.city+'. Choose a city')};
/* Homes and areas for the chosen city. Offline, fall back to the bundled sample homes (Lagos only). */
async function loadCityData(){try{const c='?city='+encodeURIComponent(state.city);const[{areas:as},{listings}]=await Promise.all([api('/areas'+c),api('/listings'+c)]);areas=as.map(toArea);const bySlug=Object.fromEntries(areas.map(a=>[a.slug,a]));const key=state.city.toLowerCase();homes=[...homes.filter(h=>h.cityKey!==key),...listings.map(l=>toHome(l,bySlug))];return true}catch{homes=sampleHomes.map(h=>({...h,cityKey:'lagos'}));areas=sampleAreas;toast('Can’t reach AreaScout right now — showing sample homes');return false}}
async function changeCity(raw,keepSearch=false){const name=String(raw).trim().replace(/\s+/g,' ').replace(/(^|[\s-])(\p{L})/gu,(_,s,c)=>s+c.toUpperCase());if(name.length<2){toast('Enter a city or town');return}document.querySelector('#modal-root').innerHTML='';state.city=name;try{localStorage.setItem('areascout-city',name)}catch{}if(!keepSearch){state.query='';state.filters={}}state.selected=null;state.loading=true;paintCity();setPage('home');await loadCityData();state.loading=false;render();if(inCity().length)toast('Showing homes in '+name)}
async function chooseCity(){let cities=[];try{cities=(await api('/locations')).cities}catch{}
 modal('Where are you looking?',`<p>Choose a city, or type any city or town.</p><div class="city-list">${cities.map(c=>`<button class="city-btn ${c.city.toLowerCase()===state.city.toLowerCase()?'on':''}" data-city="${esc(c.city)}"><b>${esc(c.city)}</b><small>${c.listing_count} ${c.listing_count===1?'home':'homes'}</small></button>`).join('')||'<small>Couldn’t load the list — type a city below.</small>'}</div><label for="city-input">Another city or town</label><input id="city-input" placeholder="e.g. Kaduna" autocomplete="off">`,'Use this place',root=>{const v=root.querySelector('#city-input').value.trim();if(!v){toast('Pick a city or type one');return}changeCity(v)})}
document.addEventListener('click',e=>{const c=e.target.closest('[data-city]');if(c){changeCity(c.dataset.city,c.hasAttribute('data-keep'));return}if(e.target.closest('#location-pill')){chooseCity();return}const act=e.target.closest('[data-action]')?.dataset.action;if(act==='choose-city')chooseCity();if(act==='alert-city')requireAuth(async()=>{try{await api('/saved-searches',{method:'POST',body:{name:'Homes in '+state.city,filters:{city:state.city}}});toast('Saved — we’ll count new homes under Profile → Saved searches')}catch(err){toast(err.message)}})});
async function boot(){paintCity();render();await loadCityData();if(token){try{state.user=(await api('/me')).user;await syncSaved();loadInspections().catch(()=>{})}catch{}}state.loading=false;paintUser();render()}

/* ---- Rate a lister after a visit; forgot password ---- */
function rateModal(inspectionId,name){modal('Rate '+(name||'your visit'),`<p>How was your visit? Your review helps the next renter.</p><div id="stars" role="radiogroup" aria-label="Rating" style="font-size:34px;letter-spacing:6px;cursor:pointer">${[1,2,3,4,5].map(n=>`<span role="radio" tabindex="0" aria-label="${n} stars" aria-checked="false" data-star="${n}" style="color:#d5dae3">★</span>`).join('')}</div>${field('rate-comment','Tell others more (optional)','maxlength="1000"')}`,'Submit review',async root=>{const n=Number(root.querySelector('#stars').dataset.value||0);if(!n){toast('Tap a star first');return}try{await api('/lister-reviews',{method:'POST',body:{inspection_id:inspectionId,rating:n,comment:root.querySelector('#rate-comment').value.trim()}});root.innerHTML='';toast('Thanks for rating');loadInspections().catch(()=>{})}catch(e){toast(e.message)}})}
function forgotPassword(email=''){modal('Forgot your password?',`<p>We’ll email you an 8-digit code to set a new one.</p>${field('fp-email','Email',`type="email" value="${esc(email)}" autocomplete="email"`)}`,'Send code',async root=>{const e=root.querySelector('#fp-email').value.trim().toLowerCase();if(!/^\S+@\S+\.\S+$/.test(e)){toast('Enter a valid email');return}try{await api('/auth/forgot-password',{method:'POST',body:{email:e}});resetPassword(e)}catch(err){toast(err.message)}})}
function resetPassword(email){modal('Enter your code',`<p>If ${esc(email)} has an account, we’ve sent an 8-digit code. It works for 30 minutes.</p>${field('rp-code','8-digit code','inputmode="numeric" maxlength="8" autocomplete="one-time-code"')}${field('rp-pw','New password','type="password" autocomplete="new-password" placeholder="At least 10 characters"')}`,'Reset password',async root=>{try{await api('/auth/reset-password',{method:'POST',body:{email,code:root.querySelector('#rp-code').value.trim(),new_password:root.querySelector('#rp-pw').value}});root.innerHTML='';toast('Password reset — you can sign in now');authModal()}catch(err){toast(err.message)}})}
document.addEventListener('click',e=>{const r=e.target.closest('[data-rate]');if(r){rateModal(Number(r.dataset.rate),r.dataset.owner);return}const st=e.target.closest('[data-star]');if(st){const box=st.parentElement,n=Number(st.dataset.star);box.dataset.value=n;box.querySelectorAll('[data-star]').forEach(x=>{const on=Number(x.dataset.star)<=n;x.style.color=on?'#e0a13a':'#d5dae3';x.setAttribute('aria-checked',String(Number(x.dataset.star)===n))});return}if(e.target.closest('[data-action="forgot"]'))forgotPassword()});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('[data-star]')){e.preventDefault();e.target.click()}});

boot();
